214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
217	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
218	        if (currentOwner != null) {
219	            Pet currentPet = this.clinicService.findPetById(petId);
220	            if (currentPet != null) {
221	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
222	                currentPet.setName(petFieldsDto.getName());
223	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
224	                this.clinicService.savePet(currentPet);
225	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
