247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Override
249	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner != null) {
252	            Pet pet = owner.getPet(petId);
253	            if (pet != null) {
254	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
255	            }
256	        }
257	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	    }
259	
260	    /**
261	     * Builds the customer code for a newly created owner, formatted
262	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
263	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
264	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
265	     * to one more than the number of owners already in that city.
266	     *
267	     * @param city     the owner's city
268	     * @param lastName the owner's last name
269	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
270	     */
271	    private String nextCustomerCode(String city, String lastName) {
272	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
273	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
274	        int sequence = 1;
275	        for (Owner existing : this.clinicService.findAllOwners()) {
276	            if (city.equalsIgnoreCase(existing.getCity())) {
277	                sequence++;
278	            }
279	        }
280	        return String.format("%s-%s-%04d", city3, last3, sequence);
281	    }
282	
283	    /**
284	     * Builds the membership number for a newly created owner, formatted
285	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
286	     * customer code and {@code YY} is the last two digits of the owner's registration
287	     * date year, zero-padded to two digits.
288	     *
289	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
290	     * @param registrationDate the owner's registration date
291	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
292	     */
293	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
294	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
295	    }
296	
297	    /**
298	     * Counts how many existing owners share the given first and last name, compared
299	     * case-insensitively. This is evaluated before the new owner is persisted, so the
300	     * owner being created is not included in the count.
301	     *
302	     * @param firstName the new owner's first name
303	     * @param lastName  the new owner's last name
304	     * @return the number of existing owners with the same first and last name
305	     */
306	    private int countNamesakes(String firstName, String lastName) {
307	        int count = 0;
308	        for (Owner existing : this.clinicService.findAllOwners()) {
309	            if (firstName.equalsIgnoreCase(existing.getFirstName())
310	                && lastName.equalsIgnoreCase(existing.getLastName())) {
311	                count++;
312	            }
313	        }
314	        return count;
315	    }
316	
317	    /**
318	     * Canonical expansions applied to common street-type abbreviations during address
319	     * normalization. Keys and values are upper-cased so the lookup runs after the address
320	     * has itself been upper-cased.
321	     */
322	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
323	        "ST", "STREET",
324	        "RD", "ROAD",
325	        "AVE", "AVENUE");
326	
327	    /**
328	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
329	     * every run of internal whitespace is collapsed to a single space, the result is
330	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
331	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
332	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
333	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
334	     * returned and compared for household duplicates; an address that is blank once
335	     * normalized fails the required-field check.
336	     *
337	     * @param address the raw address value supplied by the client
338	     * @return the normalized address (empty string when {@code address} is null or blank)
339	     */
340	    private static String normalizeAddress(String address) {
341	        if (address == null) {
342	            return "";
343	        }
344	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
345	        if (collapsed.isEmpty()) {
346	            return "";
347	        }
348	        StringBuilder normalized = new StringBuilder(collapsed.length());
349	        for (String token : collapsed.split(" ")) {
350	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
351	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
352	            if (normalized.length() > 0) {
353	                normalized.append(' ');
354	            }
355	            normalized.append(expanded != null ? expanded : token);
356	        }
357	        return normalized.toString();
358	    }
359	
360	    /**
361	     * Normalizes a last name or address for household-duplicate comparison: leading and
362	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
363	     * single space and the result is lower-cased. Two owners are considered to share a
364	     * household when both their last names and addresses produce the same key.
365	     *
366	     * @param value the raw last name or address value
367	     * @return the normalized comparison key (empty string when {@code value} is null)
368	     */
369	    private static String householdKey(String value) {
370	        if (value == null) {
371	            return "";
372	        }
373	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
374	    }
375	
376	    /**
377	     * Derives the stable shared household identifier for the given normalized last name
378	     * and address keys. The identifier is deterministic — the same household (same
379	     * {@link #householdKey normalized} last name and address) always maps to the same
380	     * value — so every owner who joins a household is assigned an identical id. It is the
381	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
382	     * '<lastNameKey>|<addressKey>'}.
383	     *
384	     * @param lastNameKey the normalized last name key
385	     * @param addressKey  the normalized address key
386	     * @return the shared household identifier
387	     */
388	    private static String householdId(String lastNameKey, String addressKey) {
389	        String source = lastNameKey + "|" + addressKey;
390	        try {
391	            byte[] digest = MessageDigest.getInstance("SHA-256")
392	                .digest(source.getBytes(StandardCharsets.UTF_8));
393	            StringBuilder hex = new StringBuilder(digest.length * 2);
394	            for (byte b : digest) {
395	                hex.append(String.format("%02x", b));
396	            }
397	            return hex.substring(0, 12).toUpperCase();
398	        } catch (NoSuchAlgorithmException e) {
399	            throw new IllegalStateException("SHA-256 not available", e);
400	        }
401	    }
402	
403	    /**
404	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
405	     * and brackets are stripped. When the number already carries a leading {@code '+'}
406	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
407	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
408	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
409	     *
410	     * @param telephone the raw telephone value supplied by the client
411	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
412	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
413	     */
414	    private static String toE164(String telephone) {
415	        if (telephone == null) {
416	            return null;
417	        }
418	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
419	        String digits;
420	        if (cleaned.startsWith("+")) {
421	            digits = cleaned.substring(1);
422	        } else {
423	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
424	            digits = "61" + national;
425	        }
426	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
427	    }
428	
429	    /**
430	     * Normalizes an owner email for creation. A present email must be a syntactically
431	     * valid address; the returned value is lower-cased.
432	     *
433	     * @param email the raw email value supplied by the client (never {@code null} here)
434	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
435	     *         address (signalling a 400 Bad Request)
436	     */
437	    private static String normalizeEmail(String email) {
438	        String trimmed = email.trim();
439	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
440	            return null;
441	        }
442	        return trimmed.toLowerCase();
443	    }
444	}
